import{_ as a,o as t,c as s,a6 as i}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"小组件 SDK、网关与叠加层边界","description":"","frontmatter":{"title":"小组件 SDK、网关与叠加层边界","docId":"developer.overlays","translationKey":"developer.overlays","locale":"zh","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"99d3351859ddb3a3304133f062f68b8e3130416947fc40433dc9c6bffaf85f6a","translationRevision":"287cfe6fe1ad033005e7fbf56a68ddf55f7269eaa052c22fe2677732d5d3d6da","order":170},"headers":[],"relativePath":"zh/developer/overlays.md","filePath":"zh/developer/overlays.md","lastUpdated":1794611623000}'),o={name:"zh/developer/overlays.md"};function d(r,e,l,n,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="widget-sdk-gateway-and-overlay-boundaries" tabindex="-1">小组件 SDK、网关与叠加层边界 <a class="header-anchor" href="#widget-sdk-gateway-and-overlay-boundaries" aria-label="Permalink to &quot;小组件 SDK、网关与叠加层边界 {#widget-sdk-gateway-and-overlay-boundaries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>构建在本地预览和 OBS 输出之间共享渲染的小组件。使用已安装的 Vue 工具链，并理解<a href="./events.html">事件</a>。本地预览不需要网关或账户凭据。实时小组件输出需要单独安装 event-gateway 插件及其限定于小组件的凭据。</p><h2 id="add-a-template" tabindex="-1">添加模板 <a class="header-anchor" href="#add-a-template" aria-label="Permalink to &quot;添加模板 {#add-a-template}&quot;">​</a></h2><ol><li>在 <code>WidgetStage</code> 内定义渲染器；相对于父元素设置尺寸，不要相对于浏览器视口。</li><li>使用 <code>src/widgets/sdk/template.ts</code> 中的 <code>defineWidget</code>，提供 schema、新建的样例封装及 <code>create(search, clock)</code> 工厂。</li><li>返回实现 <code>handleEnvelope</code>、<code>clear</code> 和 <code>dispose</code> 的控制器，以及渲染内容。使用提供的时钟，让预览可保持样例，测试可推进时间。</li><li>在 <code>sdk/templates.ts</code> 注册，再添加独立入口、构建配置、网关路由允许列表及打包条目。仅注册不会公开 URL。</li><li>编辑器和独立包使用同一个 <code>WidgetHost.vue</code>；本地预览不要嵌入网关 HTML。</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span></code></pre></div><p>文本令牌、设计默认值和可编辑字段应保留在模板 schema 中。设计序列化为 JSON，复制的小组件 URL 携带经过验证的快照；后续保存后，需向 OBS 复制更新的 URL。</p><h2 id="gateway-protocol" tabindex="-1">网关协议 <a class="header-anchor" href="#gateway-protocol" aria-label="Permalink to &quot;网关协议 {#gateway-protocol}&quot;">​</a></h2><p><code>src/widgets/shared/gateway-client.ts</code> 负责身份验证、订阅、心跳、重连和缺口报告。小组件消费规范领域封装，不直接连接 TikTok。小组件端点为 <code>/ws/widgets</code>，不同于完整外部网关客户端接口。通过共享解析器解析封装，并保留凭据边界，不要经主 WebView 传递完整网关令牌。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>内置本地预览和小组件 SDK 已实现。Cloud 叠加层编辑和 <code>cloud-overlay</code> 源码已存在，但真实 OBS 验证、图像/实时来源覆盖及包应用仍有限制。叠加层更改是尚未合并的后续工作。即使已有排行榜小组件代码，排名与竞赛在常规应用导航中仍隐藏。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>本地预览空白时，先检查控制器生命周期、schema 默认值及舞台尺寸，再考虑放宽来源策略。实时输出问题需检查网关健康、小组件凭据及明确缺口。无界面 Chromium 测试不能证明 OBS 浏览器源已通过验收。<a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/widgets/sdk" target="_blank" rel="noreferrer">小组件 SDK</a>及共享协议测试是当前实现参考。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>独立 widget 单元测试使用 fixtures；真实 gateway 的 Chromium 测试需要已构建 widget 资源及通过 <code>TIKTOOLS_PLUGINS_REPO</code> 选择的外部插件仓库。源码缺失会跳过，必须明确报告 skip。使用 <code>bun x --no-install playwright test --config src/widgets/playwright.gateway.config.ts</code> 测试该边界，随后用真实 LIVE 验证 OBS Browser Source、widget 凭据、事件传递和恢复。无头 Chromium 不能证明 OBS/原生验收。</p>`,15)])])}const g=a(o,[["render",d]]);export{u as __pageData,g as default};
